"""Cross-language goldens generated by actual UI forms, not a fake preview.

The public fixture has synthetic pins and outputs. These tests prove real
compiler/control behavior; they do not prove registry, IAM, a Task or PostgreSQL.
"""
import copy
import json
from pathlib import Path

import pytest

from generic_agents import business_flow_nested_execution_v195 as compiler
from generic_agents import full_semantic_graph_v1 as kernel
from tests.test_business_flow_nested_execution_v192 import finish

FIXTURE = Path(__file__).parent / 'fixtures/nested_execution_editor_compiler_v196.json'


def compiled(name):
    data = json.loads(FIXTURE.read_text())
    assert data['synthetic'] is True and data['not_iam_registry_or_pg_proof'] is True
    case = next(c for c in data['cases'] if c['name'] == name)
    c, e = case['ui_context'], case['expected']
    result = compiler.build_execution_graph(c['source_value'], c['flow_index'],
        e['execution_bindings'], scope_binding=case['source_binding'],
        causal_bindings=e['causal_bindings'])
    return case, result


@pytest.mark.parametrize('name', ['conditional', 'repeat'])
def test_actual_UI_form_golden_compiles_without_relaxing_native_port_or_control_gates(name):
    case, result = compiled(name)
    assert result['graph_hash'] == case['expected_graph_hash']
    assert result['source_plan'] == case['ui_context']['source_value']
    assert all(result[key] is False for key in compiler.FLAGS)
    assert compiler.check_execution_graph(result, result['source_plan'], 0,
        case['expected']['execution_bindings'], scope_binding=case['source_binding'],
        causal_bindings=case['expected']['causal_bindings']) == result


def complete(graph, state, mapping, label, value):
    node = next(n for n in graph['nodes'] if n['id'] == mapping[label])
    schema = node['output_schema'] if node['kind'] == 'human' else node['execution']['output_schema']
    assert len(schema['required']) == 1
    return finish(graph, state, node['id'], {schema['required'][0]: value})


@pytest.mark.parametrize('approved', [True, False])
def test_UI_derived_branch_uses_only_the_actual_alternative_and_survives_cold_state(approved):
    case, result = compiled('conditional'); graph = result['graph']
    mapping = {row['source_action']['name']: row['graph_node_id'] for row in result['source_mapping']['actions']}
    state = complete(graph, kernel.new_run(graph, {}, 10), mapping, '确认修复建议', approved)
    if approved:
        for label, value in [('组织通知与补核', '公开派发结果'), ('通知责任人员', '分支A真实结果'), ('核对飞行条件', False)]:
            state = complete(graph, state, mapping, label, value)
        expected = '分支A真实结果'
    else:
        state = complete(graph, state, mapping, '记录退回理由', '分支B真实结果'); expected = '分支B真实结果'
    end = next(row for row in result['source_mapping']['actions'] if row['ast_path'].endswith('/completion'))
    activation = next(a for a in state['activations'].values() if a['node_id'] == end['graph_node_id'])
    ref = case['expected']['execution_bindings']['nodes'][end['ast_path']]['input_ports'][0]['reference']
    values, _ = kernel._resolution(graph, state, kernel._metadata(graph), activation['context'], consumer_node_id=end['graph_node_id'])
    assert values[ref] == expected
    state = complete(graph, state, mapping, end['source_action']['name'], '公开核对结果')
    assert state['status'] == 'succeeded'
    assert kernel.check_run(graph, json.loads(json.dumps(state))) == state


def test_UI_derived_repeat_keeps_two_real_iterations_and_actual_stop_result():
    _, result = compiled('repeat'); graph = result['graph']
    mapping = {row['source_action']['name']: row['graph_node_id'] for row in result['source_mapping']['actions']}
    state = kernel.new_run(graph, {}, 10)
    for result_value in (True, False):
        state = complete(graph, state, mapping, '修订核查材料', '本轮真实记录')
        state = complete(graph, state, mapping, '核对飞行条件', result_value)
    end = next(row for row in result['source_mapping']['actions'] if row['ast_path'].endswith('/completion'))
    state = complete(graph, state, mapping, end['source_action']['name'], '循环结束')
    assert state['status'] == 'succeeded'
    assert kernel.check_run(graph, copy.deepcopy(state)) == state
